      function updateCameraOrbit() {
        camera.position.x =
          cameraTarget.x +
          cameraDistance * Math.sin(cameraAngleY) * Math.sin(cameraAngleX);
        camera.position.y =
          cameraTarget.y + cameraDistance * Math.cos(cameraAngleY);
        camera.position.z =
          cameraTarget.z +
          cameraDistance * Math.sin(cameraAngleY) * Math.cos(cameraAngleX);
        camera.lookAt(cameraTarget);
      }

      function setupCameraControls() {
        const dom = renderer.domElement;
        dom.style.cursor = "grab";
        dom.style.touchAction = "none";

        const joystickBase = document.getElementById("joystick-base");
        const joystickKnob = document.getElementById("joystick-knob");
        let joystickActive = false;
        let joystickBaseX = 0;
        let joystickBaseY = 0;

        const showJoystick = (x, y) => {
          joystickBase.style.left = x + "px";
          joystickBase.style.top = y + "px";
          joystickBase.style.opacity = "1";
          joystickKnob.style.transform = "translate(-50%, -50%)";
        };
        const updateJoystick = (x, y) => {
          const maxR = 48;
          let dx = x - joystickBaseX;
          let dy = y - joystickBaseY;
          const dist = Math.sqrt(dx * dx + dy * dy);
          if (dist > maxR) {
            dx = (dx / dist) * maxR;
            dy = (dy / dist) * maxR;
          }
          joystickKnob.style.transform = `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px))`;
          const dead = 10;
          state.keys.KeyA = dx < -dead;
          state.keys.KeyD = dx > dead;
          state.keys.KeyW = dy < -dead;
          state.keys.KeyS = dy > dead;
        };
        const hideJoystick = () => {
          joystickActive = false;
          joystickBase.style.opacity = "0";
          state.keys.KeyW = false;
          state.keys.KeyA = false;
          state.keys.KeyS = false;
          state.keys.KeyD = false;
        };

        const raycaster = new THREE.Raycaster();
        const pointer = new THREE.Vector2();
        let panelJoystickActive = false;
        let panelJoyStartX = 0;
        let panelJoyStartY = 0;

        const panelHit = (x, y, object) => {
          if (!object) return false;
          const rect = dom.getBoundingClientRect();
          pointer.x = ((x - rect.left) / rect.width) * 2 - 1;
          pointer.y = -((y - rect.top) / rect.height) * 2 + 1;
          raycaster.setFromCamera(pointer, camera);
          return raycaster.intersectObject(object, true).length > 0;
        };

        const resetPanelJoystick = () => {
          panelJoystickActive = false;
          state.keys.KeyW = false;
          state.keys.KeyA = false;
          state.keys.KeyS = false;
          state.keys.KeyD = false;
          if (panelJoystickBall) panelJoystickBall.position.set(-9.5, 4.65, 0);
          if (panelJoystickStick) {
            panelJoystickStick.rotation.x = 0;
            panelJoystickStick.rotation.z = 0;
          }
        };

        const updatePanelJoystick = (x, y) => {
          const max = 54;
          let dx = Math.max(-max, Math.min(max, x - panelJoyStartX));
          let dy = Math.max(-max, Math.min(max, y - panelJoyStartY));
          const dead = 9;
          state.keys.KeyA = dx < -dead;
          state.keys.KeyD = dx > dead;
          state.keys.KeyW = dy < -dead;
          state.keys.KeyS = dy > dead;
          if (panelJoystickBall) {
            panelJoystickBall.position.x = -9.5 + dx * 0.018;
            panelJoystickBall.position.z = dy * 0.018;
          }
          if (panelJoystickStick) {
            panelJoystickStick.rotation.z = -dx * 0.008;
            panelJoystickStick.rotation.x = dy * 0.008;
          }
        };

        const onDown = (x, y) => {
          if (panelHit(x, y, panelButtonHit)) {
            requestClawDrop();
            return;
          }
          if (panelHit(x, y, panelJoystickHit) || panelHit(x, y, panelJoystickBall)) {
            panelJoystickActive = true;
            panelJoyStartX = x;
            panelJoyStartY = y;
            dom.style.cursor = "grabbing";
            return;
          }
          isDragging = true;
          lastPointerX = x;
          lastPointerY = y;
          dom.style.cursor = "grabbing";
        };
        const onMove = (x, y) => {
          if (panelJoystickActive) {
            updatePanelJoystick(x, y);
            return;
          }
          if (!isDragging) return;
          const dx = x - lastPointerX;
          const dy = y - lastPointerY;
          lastPointerX = x;
          lastPointerY = y;
          cameraAngleX -= dx * 0.006;
          cameraAngleY -= dy * 0.006;
          cameraAngleY = Math.max(0.25, Math.min(1.5, cameraAngleY));
        };
        const onUp = () => {
          if (panelJoystickActive) resetPanelJoystick();
          isDragging = false;
          dom.style.cursor = "grab";
        };

        dom.addEventListener("mousedown", (e) => onDown(e.clientX, e.clientY));
        window.addEventListener("mousemove", (e) =>
          onMove(e.clientX, e.clientY)
        );
        window.addEventListener("mouseup", onUp);

        const startTouchGesture = (t) => {
          if (t.clientX < window.innerWidth / 2) {
            joystickActive = true;
            joystickBaseX = t.clientX;
            joystickBaseY = t.clientY;
            showJoystick(t.clientX, t.clientY);
          } else {
            onDown(t.clientX, t.clientY);
          }
        };

        dom.addEventListener(
          "touchstart",
          (e) => {
            if (e.touches.length === 1) {
              startTouchGesture(e.touches[0]);
            } else if (e.touches.length === 2) {
              hideJoystick();
              isDragging = false;
              pinchStartDist = touchDist(e.touches[0], e.touches[1]);
              pinchStartCameraDistance = cameraDistance;
            }
          },
          { passive: true }
        );
        dom.addEventListener(
          "touchmove",
          (e) => {
            if (e.touches.length === 1) {
              if (joystickActive) {
                updateJoystick(e.touches[0].clientX, e.touches[0].clientY);
              } else {
                onMove(e.touches[0].clientX, e.touches[0].clientY);
              }
            } else if (e.touches.length === 2) {
              const d = touchDist(e.touches[0], e.touches[1]);
              const ratio = pinchStartDist / d;
              cameraDistance = Math.max(
                25,
                Math.min(220, pinchStartCameraDistance * ratio)
              );
            }
          },
          { passive: true }
        );
        dom.addEventListener("touchend", (e) => {
          if (e.touches.length === 0) {
            hideJoystick();
            onUp();
          } else if (e.touches.length === 1) {
            hideJoystick();
            isDragging = false;
            startTouchGesture(e.touches[0]);
          }
        });

        dom.addEventListener(
          "wheel",
          (e) => {
            e.preventDefault();
            cameraDistance = Math.max(
              25,
              Math.min(220, cameraDistance + e.deltaY * 0.05)
            );
          },
          { passive: false }
        );
      }

      function initPhysics() {
        world = new CANNON.World();
        world.gravity.set(0, CFG.grav, 0);
        // SAP é muito mais eficiente para muitos prêmios dentro de uma área fechada.
        world.broadphase = new CANNON.SAPBroadphase(world);
        world.broadphase.axisIndex = 1;
        world.solver.iterations = 24;
        world.solver.tolerance = 0.0015;
        world.allowSleep = true;

        defaultMat = new CANNON.Material("default");
        floorMat = new CANNON.Material("floor");

        contactMat = new CANNON.ContactMaterial(defaultMat, defaultMat, {
          friction: CFG.fric,
          restitution: CFG.rest,
        });

        floorContact = new CANNON.ContactMaterial(floorMat, defaultMat, {
          friction: CFG.fric + 0.5,
          restitution: CFG.rest * 0.1,
        });

        world.addContactMaterial(contactMat);
        world.addContactMaterial(floorContact);
      }

