      function makePanelDisplay(label, initialValue) {
        const canvas = document.createElement("canvas");
        canvas.width = 256;
        canvas.height = 160;
        const ctx = canvas.getContext("2d");
        const tex = new THREE.CanvasTexture(canvas);
        tex.encoding = THREE.sRGBEncoding;
        const mat = new THREE.MeshBasicMaterial({ map: tex });
        const mesh = new THREE.Mesh(new THREE.PlaneGeometry(4.7, 2.9), mat);
        mesh.userData.displayLabel = label;
        mesh.userData.displayValue = initialValue;
        return { canvas, ctx, tex, mesh };
      }

      function drawPanelDisplay(ctx, tex, label, value, low) {
        ctx.clearRect(0, 0, 256, 160);
        ctx.fillStyle = "#05060a";
        ctx.fillRect(0, 0, 256, 160);
        ctx.strokeStyle = low ? "#ff3355" : "#9b4dff";
        ctx.lineWidth = 8;
        ctx.strokeRect(6, 6, 244, 148);
        ctx.textAlign = "center";
        ctx.fillStyle = "#d9b8ff";
        ctx.font = "bold 25px Segoe UI";
        ctx.fillText(label, 128, 38);
        ctx.shadowColor = low ? "#ff0033" : "#a64dff";
        ctx.shadowBlur = 22;
        ctx.fillStyle = low ? "#ff6680" : "#ffffff";
        ctx.font = "bold 72px monospace";
        ctx.fillText(String(value), 128, 116);
        ctx.shadowBlur = 0;
        tex.needsUpdate = true;
      }

