      function createClaw() {
        if (clawGroup && railPivot) railPivot.remove(clawGroup);
        state.fingerBodies.forEach((b) => world.removeBody(b));
        state.fingerBodies = [];
        if (state.clawCoreBody) world.removeBody(state.clawCoreBody);
        state.clawCoreBody = null;

        clawGroup = new THREE.Group();

        const chrome = new THREE.MeshStandardMaterial({
          color: 0xdfe7ee,
          roughness: 0.12,
          metalness: 1.0,
          envMapIntensity: 1.8,
        });
        const chromeDark = new THREE.MeshStandardMaterial({
          color: 0x66717d,
          roughness: 0.2,
          metalness: 0.95,
          envMapIntensity: 1.4,
        });
        const blackRubber = new THREE.MeshStandardMaterial({
          color: 0x111214,
          roughness: 0.72,
          metalness: 0.05,
        });

        // Cabo espiral: ele acompanha o mesmo balanço físico da garra e
        // estica/encolhe junto com a descida e a subida.
        const cableCurve = new THREE.Curve();
        cableCurve.getPoint = function (t) {
          const turns = 28;
          const radius = 0.34;
          const a = t * Math.PI * 2 * turns;
          return new THREE.Vector3(
            Math.cos(a) * radius,
            t * 40,
            Math.sin(a) * radius
          );
        };
        const cableCoil = new THREE.Mesh(
          new THREE.TubeGeometry(cableCurve, 360, 0.085, 8, false),
          blackRubber
        );
        cableCoil.castShadow = true;
        clawCab = new THREE.Group();
        clawCab.add(cableCoil);
        const cableCore = new THREE.Mesh(
          new THREE.CylinderGeometry(0.07, 0.07, 40, 8),
          blackRubber
        );
        cableCore.position.y = 20;
        clawCab.add(cableCore);
        clawGroup.add(clawCab);

        // Corpo cilíndrico cromado semelhante ao do vídeo.
        const body = new THREE.Mesh(
          new THREE.CylinderGeometry(1.55, 1.72, 3.0, 32),
          chrome
        );
        body.position.y = -0.65;
        body.castShadow = true;
        clawGroup.add(body);

        const topCap = new THREE.Mesh(
          new THREE.CylinderGeometry(1.62, 1.62, 0.28, 32),
          chromeDark
        );
        topCap.position.y = 0.95;
        clawGroup.add(topCap);

        const lowerRing = new THREE.Mesh(
          new THREE.TorusGeometry(1.58, 0.16, 10, 32),
          chromeDark
        );
        lowerRing.rotation.x = Math.PI / 2;
        lowerRing.position.y = -2.05;
        clawGroup.add(lowerRing);

        const centerRod = new THREE.Mesh(
          new THREE.CylinderGeometry(0.22, 0.22, 2.2, 16),
          chromeDark
        );
        centerRod.position.y = -2.8;
        clawGroup.add(centerRod);

        function cylinderBetween(a, b, radius, material) {
          const mid = a.clone().add(b).multiplyScalar(0.5);
          const dir = b.clone().sub(a);
          const mesh = new THREE.Mesh(
            new THREE.CylinderGeometry(radius, radius, dir.length(), 14),
            material
          );
          mesh.position.copy(mid);
          mesh.quaternion.setFromUnitVectors(
            new THREE.Vector3(0, 1, 0),
            dir.clone().normalize()
          );
          mesh.castShadow = true;
          return mesh;
        }

        fingers = [];
        for (let i = 0; i < 3; i++) {
          const anchor = new THREE.Group();
          anchor.rotation.y = i * ((Math.PI * 2) / 3);
          clawGroup.add(anchor);

          const pivot = new THREE.Group();
          pivot.position.set(0, -1.7, 1.3);
          anchor.add(pivot);

          const upperJoint = new THREE.Mesh(
            new THREE.CylinderGeometry(0.34, 0.34, 0.45, 18),
            chromeDark
          );
          upperJoint.rotation.z = Math.PI / 2;
          pivot.add(upperJoint);

          const upperA = new THREE.Vector3(-0.18, -0.15, 0.05);
          const upperB = new THREE.Vector3(-0.12, -2.25, 0.82);
          const upperBar1 = cylinderBetween(upperA, upperB, 0.13, chrome);
          const upperBar2 = cylinderBetween(
            upperA.clone().add(new THREE.Vector3(0.36, 0, 0)),
            upperB.clone().add(new THREE.Vector3(0.36, 0, 0)),
            0.13,
            chrome
          );
          pivot.add(upperBar1, upperBar2);

          const knuckle = new THREE.Mesh(
            new THREE.CylinderGeometry(0.38, 0.38, 0.55, 18),
            chromeDark
          );
          knuckle.rotation.z = Math.PI / 2;
          knuckle.position.set(0.06, -2.25, 0.82);
          pivot.add(knuckle);

          const lowerA = new THREE.Vector3(-0.08, -2.3, 0.82);
          const lowerB = new THREE.Vector3(-0.03, -4.35, 0.42);
          pivot.add(cylinderBetween(lowerA, lowerB, 0.12, chrome));
          pivot.add(
            cylinderBetween(
              lowerA.clone().add(new THREE.Vector3(0.28, 0, 0)),
              lowerB.clone().add(new THREE.Vector3(0.28, 0, 0)),
              0.12,
              chrome
            )
          );

          const hookCurve = new THREE.CatmullRomCurve3([
            new THREE.Vector3(0.11, -4.3, 0.42),
            new THREE.Vector3(0.1, -4.85, 0.25),
            new THREE.Vector3(0.08, -5.25, -0.05),
            new THREE.Vector3(0.06, -5.35, -0.52),
            new THREE.Vector3(0.04, -5.05, -0.82),
          ]);
          const talon = new THREE.Mesh(
            new THREE.TubeGeometry(hookCurve, 28, 0.13, 10, false),
            chrome
          );
          talon.castShadow = true;
          pivot.add(talon);

          const bolt = new THREE.Mesh(
            new THREE.CylinderGeometry(0.14, 0.14, 0.62, 16),
            blackRubber
          );
          bolt.rotation.z = Math.PI / 2;
          bolt.position.copy(knuckle.position);
          pivot.add(bolt);

          fingers.push({
            mesh: pivot,
            angleOffset: i * ((Math.PI * 2) / 3),
          });

          const b = new CANNON.Body({ mass: 0, type: CANNON.Body.KINEMATIC });
          // Corpo composto mais espesso: três esferas impedem tunneling e
          // empurram os prêmios ao longo de toda a haste.
          b.addShape(new CANNON.Sphere(0.48), new CANNON.Vec3(0, 1.55, 0));
          b.addShape(new CANNON.Sphere(0.52), new CANNON.Vec3(0, 0, 0));
          b.addShape(new CANNON.Sphere(0.46), new CANNON.Vec3(0, -1.55, 0));
          b.addShape(new CANNON.Box(new CANNON.Vec3(0.34, 1.7, 0.34)));
          b.position.set(0, -100, 0);
          b.collisionFilterGroup = G_CLAW;
          b.collisionFilterMask = G_PRIZE | G_DEFAULT;
          b.collisionResponse = true;
          b._lastPosition = new CANNON.Vec3(0, -100, 0);
          world.addBody(b);
          state.fingerBodies.push(b);
        }

        // Proxy físico do corpo central da garra. Sem este corpo, os
        // prêmios atravessavam o cilindro cromado entre as hastes.
        const coreBody = new CANNON.Body({
          mass: 0,
          type: CANNON.Body.KINEMATIC,
        });
        coreBody.addShape(new CANNON.Sphere(1.72), new CANNON.Vec3(0, -0.8, 0));
        coreBody.addShape(new CANNON.Sphere(1.38), new CANNON.Vec3(0, -2.45, 0));
        coreBody.position.set(0, -100, 0);
        coreBody.collisionFilterGroup = G_CLAW;
        coreBody.collisionFilterMask = G_PRIZE | G_DEFAULT;
        coreBody.collisionResponse = true;
        coreBody._lastPosition = new CANNON.Vec3(0, -100, 0);
        world.addBody(coreBody);
        state.clawCoreBody = coreBody;

        if (!railPivot) {
          railPivot = new THREE.Group();
          railPivot.position.y = 41;
          scene.add(railPivot);
        }
        railPivot.add(clawGroup);

        const cl = new THREE.SpotLight(0xffffff, 1.5, 55, 1.0, 1.0, 1);
        cl.position.y = -1.2;
        cl.target.position.set(0, -10, 0);
        clawGroup.add(cl);
        clawGroup.add(cl.target);
      }


      let SPECIAL_PRIZES = ["PRÊMIO SURPRESA"];

      fetch("/api/game?acao=premios-disponiveis")
        .then(r => r.ok ? r.json() : Promise.reject())
        .then(d => { if (Array.isArray(d.premios) && d.premios.length) SPECIAL_PRIZES = d.premios; })
        .catch(() => {});

      function randomSpecialPrize() {
        return SPECIAL_PRIZES[Math.floor(Math.random() * SPECIAL_PRIZES.length)];
      }

      function createPrizeLabel(text, width = 2.35, height = 0.72) {
        const canvas = document.createElement('canvas');
        canvas.width = 768;
        canvas.height = 240;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#050505';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.strokeStyle = '#ffd12f';
        ctx.lineWidth = 12;
        ctx.strokeRect(8, 8, canvas.width - 16, canvas.height - 16);
        ctx.fillStyle = '#ffd12f';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.font = '900 58px Arial, Helvetica, sans-serif';
        const words = text.split(' ');
        const lines = [];
        let line = '';
        for (const word of words) {
          const test = line ? `${line} ${word}` : word;
          if (ctx.measureText(test).width > 680 && line) {
            lines.push(line);
            line = word;
          } else line = test;
        }
        if (line) lines.push(line);
        const visible = lines.slice(0, 3);
        const step = 62;
        const startY = canvas.height / 2 - ((visible.length - 1) * step) / 2;
        visible.forEach((value, index) => ctx.fillText(value, canvas.width / 2, startY + index * step));
        const tex = new THREE.CanvasTexture(canvas);
        tex.anisotropy = renderer.capabilities.getMaxAnisotropy();
        const mat = new THREE.MeshBasicMaterial({ map: tex });
        return new THREE.Mesh(new THREE.PlaneGeometry(width, height), mat);
      }

      function makePrizeMaterial(color, metalness = 0.15, roughness = 0.45) {
        return new THREE.MeshStandardMaterial({ color, metalness, roughness });
      }

      function createGiftPrize(scale = 1) {
        const group = new THREE.Group();
        const black = makePrizeMaterial(0x080808, 0.2, 0.32);
        const gold = makePrizeMaterial(0xffc83d, 0.92, 0.2);

        const box = new THREE.Mesh(new THREE.BoxGeometry(2.7, 2.35, 2.7), black);
        box.position.y = -0.15;
        group.add(box);

        const lid = new THREE.Mesh(new THREE.BoxGeometry(2.95, 0.52, 2.95), black);
        lid.position.y = 1.22;
        group.add(lid);

        const ribbonV = new THREE.Mesh(new THREE.BoxGeometry(0.48, 2.95, 2.92), gold);
        ribbonV.position.y = 0.12;
        group.add(ribbonV);

        const ribbonH = new THREE.Mesh(new THREE.BoxGeometry(2.92, 0.48, 0.48), gold);
        ribbonH.position.y = 1.24;
        group.add(ribbonH);

        const knot = new THREE.Mesh(new THREE.SphereGeometry(0.38, 14, 10), gold);
        knot.scale.set(1.2, 0.7, 1.0);
        knot.position.y = 1.88;
        group.add(knot);

        for (const side of [-1, 1]) {
          const loop = new THREE.Mesh(new THREE.TorusGeometry(0.58, 0.17, 10, 22, Math.PI * 1.55), gold);
          loop.rotation.set(Math.PI / 2, 0, side * 0.5);
          loop.position.set(side * 0.62, 1.93, 0);
          group.add(loop);
        }

        group.scale.setScalar(scale);
        group.traverse((o) => {
          if (o.isMesh) {
            o.castShadow = true;
            o.receiveShadow = true;
          }
        });
        const prizeName = randomSpecialPrize();
        const labelFront = createPrizeLabel(prizeName);
        labelFront.position.set(0, 0.05, 1.365);
        group.add(labelFront);
        const labelBack = labelFront.clone();
        labelBack.position.z = -1.365;
        labelBack.rotation.y = Math.PI;
        group.add(labelBack);
        group.userData.prizeType = 'gift';
        group.userData.prizeName = prizeName;
        return group;
      }

      function createLogoPrize(scale = 1) {
        const group = new THREE.Group();
        const gold = makePrizeMaterial(0xffd12f, 0.92, 0.16);
        const black = makePrizeMaterial(0x080808, 0.28, 0.32);
        const copper = makePrizeMaterial(0xc97845, 0.9, 0.22);

        // Medalhão 3D: deixa a marca legível mesmo quando o prêmio gira.
        const body = new THREE.Mesh(
          new THREE.CylinderGeometry(1.62, 1.62, 0.42, 48),
          black
        );
        body.rotation.x = Math.PI / 2;
        group.add(body);

        const rim = new THREE.Mesh(
          new THREE.TorusGeometry(1.46, 0.105, 12, 56),
          gold
        );
        rim.position.z = 0.235;
        group.add(rim);

        const rimBack = rim.clone();
        rimBack.position.z = -0.235;
        group.add(rimBack);

        // Desenha o @ dourado em um canvas transparente e aplica nas duas faces.
        const canvas = document.createElement('canvas');
        canvas.width = 512;
        canvas.height = 512;
        const ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, 512, 512);
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.font = '900 390px Arial, Helvetica, sans-serif';
        ctx.lineJoin = 'round';
        ctx.lineWidth = 18;
        ctx.strokeStyle = '#6f4700';
        ctx.strokeText('@', 256, 258);
        const grad = ctx.createLinearGradient(80, 70, 430, 440);
        grad.addColorStop(0, '#fff1a3');
        grad.addColorStop(0.35, '#ffd62f');
        grad.addColorStop(0.75, '#e8a900');
        grad.addColorStop(1, '#fff0a0');
        ctx.fillStyle = grad;
        ctx.fillText('@', 256, 258);

        const logoTexture = new THREE.CanvasTexture(canvas);
        logoTexture.anisotropy = renderer.capabilities.getMaxAnisotropy();
        logoTexture.needsUpdate = true;
        const logoMat = new THREE.MeshBasicMaterial({
          map: logoTexture,
          transparent: true,
          side: THREE.DoubleSide,
          depthWrite: false,
        });

        const frontLogo = new THREE.Mesh(
          new THREE.PlaneGeometry(2.72, 2.72),
          logoMat
        );
        frontLogo.position.z = 0.246;
        group.add(frontLogo);

        const backLogo = frontLogo.clone();
        backLogo.position.z = -0.246;
        backLogo.rotation.y = Math.PI;
        group.add(backLogo);

        // Pequeno cabo/conector igual ao detalhe da marca.
        const cable = new THREE.Mesh(
          new THREE.TorusGeometry(1.56, 0.12, 12, 48, Math.PI * 0.34),
          gold
        );
        cable.rotation.z = -1.30;
        cable.position.set(0.16, -0.05, 0.02);
        group.add(cable);

        const plugBase = new THREE.Mesh(
          new THREE.CylinderGeometry(0.27, 0.34, 0.38, 16),
          black
        );
        plugBase.rotation.z = Math.PI / 2;
        plugBase.position.set(1.72, -1.05, 0.02);
        group.add(plugBase);

        for (let i = 0; i < 4; i++) {
          const angle = (i / 4) * Math.PI * 2;
          const y = -1.05 + Math.sin(angle) * 0.16;
          const z = 0.02 + Math.cos(angle) * 0.16;

          const wire = new THREE.Mesh(
            new THREE.CylinderGeometry(0.052, 0.052, 0.34, 8),
            black
          );
          wire.rotation.z = Math.PI / 2;
          wire.position.set(1.98, y, z);
          group.add(wire);

          const tip = new THREE.Mesh(
            new THREE.CylinderGeometry(0.043, 0.043, 0.14, 8),
            copper
          );
          tip.rotation.z = Math.PI / 2;
          tip.position.set(2.22, y, z);
          group.add(tip);
        }

        group.scale.setScalar(scale);
        group.traverse((o) => {
          if (o.isMesh) {
            o.castShadow = true;
            o.receiveShadow = true;
          }
        });
        group.userData.prizeType = 'logo';
        group.userData.prizeName = randomSpecialPrize();
        return group;
      }

      function spawnPrizes() {
        prizes.forEach((p) => {
          scene.remove(p.mesh);
          world.removeBody(p.body);
        });
        prizes = [];
        const geos = [
          new THREE.IcosahedronGeometry(1.5),
          new THREE.DodecahedronGeometry(1.5),
          new THREE.BoxGeometry(2, 2, 2),
          new THREE.TorusGeometry(1, 0.4, 16, 32),
        ];

        const spawnedPos = [];

        for (let i = 0; i < CFG.pCount; i++) {
          let x, y, z;
          let attempts = 0;
          let safe = false;

          do {
            attempts++;
            x = (Math.random() - 0.5) * 22;
            z = (Math.random() - 0.5) * 22;
            if (x < -2 && z > 2) continue;

            y = 5 + Math.random() * 20;

            let overlaps = false;
            for (let prev of spawnedPos) {
              const dist = Math.sqrt(
                (x - prev.x) ** 2 + (y - prev.y) ** 2 + (z - prev.z) ** 2
              );
              if (dist < 3.5) {
                overlaps = true;
                break;
              }
            }

            if (!overlaps) {
              safe = true;
              spawnedPos.push({ x, y, z });
            }
          } while (!safe && attempts < 50);

          if (!safe && attempts >= 50) continue;

          const col = new THREE.Color().setHSL(Math.random(), 0.8, 0.5);
          const isGlass = Math.random() < 1.0 - CFG.pRatio;

          let mat, mesh;
          const specialRoll = Math.random();
          if (specialRoll < 0.14) {
            mesh = createLogoPrize(CFG.pScale * 0.78);
          } else if (specialRoll < 0.30) {
            mesh = createGiftPrize(CFG.pScale * 0.72);
          } else if (isGlass) {
            mat = new THREE.MeshPhysicalMaterial({
              color: col,
              roughness: 0.4,
              metalness: 0.1,
              transmission: 0.6,
              thickness: 2.5,
              ior: 1.5,
              clearcoat: 1.0,
              side: THREE.DoubleSide,
              transparent: true,
              opacity: 1.0,
            });
            mesh = new THREE.Mesh(
              geos[Math.floor(Math.random() * geos.length)],
              mat
            );
          } else {
            mat = new THREE.MeshStandardMaterial({
              color: col,
              roughness: 0.6,
              metalness: 0.1,
            });
            mesh = new THREE.Mesh(
              geos[Math.floor(Math.random() * geos.length)],
              mat
            );
          }

          if (!mesh.userData.prizeType) mesh.scale.setScalar(CFG.pScale);
          mesh.traverse((o) => {
            if (o.isMesh) {
              o.castShadow = true;
              o.receiveShadow = true;
            }
          });
          mesh.position.set(x, y, z);
          mesh.rotation.set(
            Math.random() * 6.28,
            Math.random() * 6.28,
            Math.random() * 6.28
          );
          scene.add(mesh);

          const prizeType = mesh.userData.prizeType;
          const bodyMass = prizeType === 'gift' ? 9.0 : prizeType === 'logo' ? 7.5 : 5.2;
          const body = new CANNON.Body({ mass: bodyMass, material: defaultMat });

          // Colliders mais próximos do formato real evitam que caixas e medalhas
          // rolem como bolas ou fiquem "flutuando" umas sobre as outras.
          if (prizeType === 'gift') {
            body.addShape(new CANNON.Box(new CANNON.Vec3(
              1.35 * CFG.pScale,
              1.25 * CFG.pScale,
              1.35 * CFG.pScale
            )));
          } else if (prizeType === 'logo') {
            body.addShape(new CANNON.Cylinder(
              1.45 * CFG.pScale,
              1.45 * CFG.pScale,
              0.72 * CFG.pScale,
              16
            ));
          } else {
            body.addShape(new CANNON.Sphere(1.35 * CFG.pScale));
          }

          body.position.copy(mesh.position);
          // Mais peso e amortecimento reduzem quique e impedem que os prêmios
          // sejam arremessados quando os dedos da garra fecham.
          body.linearDamping = 0.38;
          body.angularDamping = 0.76;
          body.allowSleep = true;
          body.sleepSpeedLimit = 0.24;
          body.sleepTimeLimit = 0.55;
          body.ccdSpeedThreshold = 1.5;
          body.ccdIterations = 4;
          body.collisionFilterGroup = G_PRIZE;
          body.collisionFilterMask = G_DEFAULT | G_PRIZE | G_CLAW;

          world.addBody(body);
          prizes.push({ mesh, body });
        }
      }

      async function setupSettings() {
        const panel = document.getElementById("settings-panel");
        const overlay = document.getElementById("settings-overlay");
        const hamburger = document.getElementById("hamburger");
        panel.style.display = "none";
        overlay.style.display = "none";
        hamburger.style.display = "none";

        const adminMode = new URLSearchParams(location.search).get("admin") === "1";
        const adminToken = sessionStorage.getItem("atos_admin_token") || "";
        if (!adminMode || !adminToken) return;
        try {
          const resp = await fetch("/api/admin?acao=validar", {
            headers: { Authorization: `Bearer ${adminToken}` }
          });
          if (!resp.ok) return;
        } catch (_) { return; }
        hamburger.style.display = "block";

        const toggleMenu = () => {
          const isOpen = panel.style.display === "flex";
          panel.style.display = isOpen ? "none" : "flex";
          overlay.style.display = isOpen ? "none" : "block";
        };
        hamburger.onclick = toggleMenu;
        overlay.onclick = toggleMenu;
        window.addEventListener("keydown", (e) => {
          if (e.key === "Escape" && panel.style.display === "flex")
            toggleMenu();
        });

        const randColor = () =>
          "#" + Math.floor(Math.random() * 16777215).toString(16);

        document.getElementById("btn-rand-cols").onclick = () => {
          const ids = [
            "col-frame",
            "col-floor",
            "col-glass",
            "col-chute",
            "col-l1",
            "col-l2",
            "col-l3",
            "col-l4",
          ];
          ids.forEach((id) => {
            const el = document.getElementById(id);
            el.value = randColor();
            el.dispatchEvent(new Event("input"));
          });
        };

        document.getElementById("btn-rand-sets").onclick = () => {
          const rnd = (min, max) => Math.random() * (max - min) + min;

          const sets = [
            { id: "set-p-grav", min: -100, max: -5 },
            { id: "set-c-speed", min: 10, max: 50 },
            { id: "set-c-grip", min: 0.5, max: 2.0 },
            { id: "set-p-rest", min: 0.1, max: 0.9 },
          ];

          sets.forEach((s) => {
            const el = document.getElementById(s.id);
            el.value = rnd(s.min, s.max);
            el.dispatchEvent(new Event("input"));
          });
        };

        // DEBOUNCE SPAWN
        let spawnTimer;
        const triggerSpawn = () => {
          clearTimeout(spawnTimer);
          spawnTimer = setTimeout(spawnPrizes, 200);
        };

        const bind = (id, obj, key, isCol = false) => {
          const el = document.getElementById(id);
          el.oninput = (e) => {
            // FIX: Check isCol correctly
            const val = isCol ? e.target.value : parseFloat(e.target.value);
            if (!isCol) {
              const disp = document.getElementById(
                id.replace("set", "val").replace("col", "val")
              );
              if (disp) disp.innerText = val.toFixed ? val.toFixed(2) : val;
            }

            if (id === "col-chute") {
              mats.chuteCore.color.set(val);
              mats.chuteGlow.color.set(val);
              mats.chuteGlow.emissive.set(val);
            } else if (id === "col-frame") mats.frame.color.set(val);
            else if (id === "col-floor") mats.floor.color.set(val);
            else if (id === "col-glass") mats.glass.color.set(val);
            else if (id.startsWith("col-l")) {
              const idx = parseInt(id.charAt(5)) - 1;
              if (state.lights[idx]) state.lights[idx].obj.color.set(val);
            } else if (id === "set-g-opac") mats.glass.opacity = val;
            else if (id === "set-g-rough") mats.glass.roughness = val;
            else if (id === "set-f-rough") mats.frame.roughness = val;
            else if (id === "set-f-metal") mats.frame.metalness = val;
            else if (id === "set-p-grav") world.gravity.set(0, val, 0);
            else if (id === "set-p-rest") {
              contactMat.restitution = val;
              floorContact.restitution = val * 0.1;
            } else if (id === "set-p-fric") {
              contactMat.friction = val;
              floorContact.friction = val + 0.5;
            } else if (id === "set-p-damp")
              prizes.forEach((p) => (p.body.linearDamping = val));
            // CONFIG UPDATES
            else if (id === "set-c-speed") CFG.clawSpeed = val;
            else if (id === "set-c-drop") CFG.dropSpeed = val;
            else if (id === "set-c-lift") CFG.liftSpeed = val;
            else if (id === "set-c-grip") CFG.gripStrength = val;
            else if (id === "set-c-rad") CFG.grabRadius = val;
            // SPAWN TRIGGERS
            else if (id === "set-g-count") {
              CFG.pCount = val;
              triggerSpawn();
            } else if (id === "set-g-scale") {
              CFG.pScale = val;
              triggerSpawn();
            } else if (id === "set-g-ratio") {
              CFG.pRatio = val;
              triggerSpawn();
            } else if (obj) obj[key] = val;
          };
        };

        [
          "set-c-speed",
          "set-c-drop",
          "set-c-lift",
          "set-c-grip",
          "set-c-rad",
          "set-g-count",
          "set-g-scale",
          "set-g-ratio",
        ].forEach((id) => bind(id, null, null));

        [
          "set-g-opac",
          "set-g-rough",
          "set-f-rough",
          "set-f-metal",
          "set-p-grav",
          "set-p-rest",
          "set-p-fric",
          "set-p-damp",
          "col-frame",
          "col-floor",
          "col-glass",
          "col-chute",
          "col-l1",
          "col-l2",
          "col-l3",
          "col-l4",
        ].forEach((id) => bind(id, {}, "", id.startsWith("col-"))); // Pass true for colors

        document.getElementById("btn-respawn").onclick = spawnPrizes;
        document.getElementById("btn-shuffle").onclick = () => {
          prizes.forEach((p) =>
            p.mesh.material.color.setHSL(Math.random(), 0.8, 0.5)
          );
        };
      }

      function startRoundOnFirstMovement() {
        if (state.mode !== "IDLE" || state.creditCharged) return true;
        if (!atosCreditosCarregados || atosCreditoPendente) return false;
        if (state.credits <= 0) {
          state.keys.KeyW = state.keys.KeyA = state.keys.KeyS = state.keys.KeyD = false;
          showNoCreditsMessage();
          return false;
        }

        // O cronômetro e o desconto começam no PRIMEIRO movimento, inclusive
        // no joystick do celular e no joystick 3D. chargeCredit marca o crédito
        // como consumido antes de aguardar a rede, portanto não há delay visual.
        state.timerValue = TIMER_DURATION;
        state.timerActive = true;
        chargeCredit();
        return true;
      }

      function setupInput() {
        requestClawDrop = async () => {
          if (state.mode !== "IDLE") return false;
          if (!state.creditCharged && !(await chargeCredit())) return false;
          state.mode = "DESCENDING";
          state.timerActive = false;
          moveSound.pause();
          state.moving = false;
          playClawEffect(clawDescendingSound);
          return true;
        };

        const onKey = (k, v) => {
          const isMovement = ["KeyW", "KeyA", "KeyS", "KeyD"].includes(k);
          state.keys[k] = v;
          if (isMovement && v) startRoundOnFirstMovement();
          if (k === "Space" && v) requestClawDrop();
        };
        // Controles de teclado robustos. Usamos addEventListener para não serem
        // sobrescritos por outros componentes do painel/câmera.
        const movementCodes = new Set(["KeyW", "KeyA", "KeyS", "KeyD", "Space"]);
        const normalizeKey = (e) => {
          if (e.code && movementCodes.has(e.code)) return e.code;
          const key = String(e.key || "").toLowerCase();
          return ({ w: "KeyW", a: "KeyA", s: "KeyS", d: "KeyD", " ": "Space" })[key] || e.code;
        };
        window.addEventListener("keydown", (e) => {
          const code = normalizeKey(e);
          if (!movementCodes.has(code)) return;
          e.preventDefault();
          onKey(code, true);
        }, { passive: false });
        window.addEventListener("keyup", (e) => {
          const code = normalizeKey(e);
          if (!movementCodes.has(code)) return;
          e.preventDefault();
          onKey(code, false);
        }, { passive: false });
        window.addEventListener("blur", () => {
          ["KeyW", "KeyA", "KeyS", "KeyD", "Space"].forEach((code) => onKey(code, false));
        });

      }

      function updateGame(dt) {
        sceneTime += dt;
        state.lights.forEach((l) => {
          const t = sceneTime;
          l.obj.position.x = Math.sin(t * l.spdX + l.offX) * l.radX;
          l.obj.position.z = Math.cos(t * l.spdZ + l.offZ) * l.radZ;
          l.obj.position.y = l.yBase + Math.sin(t * 0.2 + l.offX) * 20;
        });

        if (
          state.grabbed &&
          (state.mode === "ASCENDING" || state.mode === "RETURNING")
        ) {
          const slipChance =
            (1.1 - Math.min(CFG.gripStrength, 1.1)) * 0.35 * dt;
          if (Math.random() < slipChance) {
            const g = state.grabbed;
            g.body.type = CANNON.Body.DYNAMIC;
            g.body.collisionFilterMask = G_DEFAULT | G_PRIZE | G_CLAW;
            g.body.velocity.set(
              (Math.random() - 0.5) * 4,
              -2,
              (Math.random() - 0.5) * 4
            );
            g.body.wakeUp();
            state.grabbed = null;
          }
        }

        if (state.mode === "IDLE") {
          const spd = CFG.clawSpeed * dt;
          const isMoving =
            state.keys.KeyA ||
            state.keys.KeyD ||
            state.keys.KeyW ||
            state.keys.KeyS;

          if (isMoving && !state.moving) {
            moveSound.currentTime = 0;
            moveSound
              .play()
              .catch((err) => console.warn("Falha ao tocar som:", err));
          } else if (!isMoving && state.moving) {
            moveSound.pause();
          }
          state.moving = isMoving;

          if (isMoving && !state.creditCharged) {
            startRoundOnFirstMovement();
          }

          const oldX = state.claw.x;
          const oldZ = state.claw.z;
          if (state.keys.KeyA) state.claw.x -= spd;
          if (state.keys.KeyD) state.claw.x += spd;
          if (state.keys.KeyW) state.claw.z -= spd;
          if (state.keys.KeyS) state.claw.z += spd;

          // Limites internos: vidros laterais, fundo e vidro frontal.
          state.claw.x = THREE.MathUtils.clamp(state.claw.x, -15 + CLAW_WALL_MARGIN, 15 - CLAW_WALL_MARGIN);
          state.claw.z = THREE.MathUtils.clamp(state.claw.z, -15 + CLAW_WALL_MARGIN, 15 - CLAW_WALL_MARGIN);
          // Acima da divisória a garra pode cruzar normalmente. Quando está
          // baixa, o movimento horizontal é bloqueado antes do contato.
          if (
            state.claw.y - CLAW_LOWEST_OFFSET < BARRIER_TOP_Y + 0.15 &&
            clawOverWhiteBarrier(state.claw.x, state.claw.z)
          ) {
            state.claw.x = oldX;
            state.claw.z = oldZ;
          }

          if (state.timerActive) {
            state.timerValue -= dt;
            if (state.timerValue <= 0) {
              state.timerValue = 0;
              state.timerActive = false;
              state.mode = "DESCENDING";
              playClawEffect(clawDescendingSound);
            }
          }

          clawGroup.rotation.x = 0;
          clawGroup.rotation.z = 0;

          fingers.forEach(
            (f) =>
              (f.mesh.rotation.x = THREE.MathUtils.lerp(
                f.mesh.rotation.x,
                -0.3,
                0.1
              ))
          );
        }

        const displayVal = Math.ceil(state.timerValue);
        const timerEl = document.getElementById("timer-val");
        if (timerEl) {
          timerEl.innerText = displayVal;
          timerEl.classList.toggle("low", state.timerActive && displayVal <= 10);
        }
        if (panelTimeCtx) drawPanelDisplay(panelTimeCtx, panelTimeTex, "TEMPO", displayVal, state.timerActive && displayVal <= 10);

        if (state.mode === "DESCENDING") {
          state.claw.y -= CFG.dropSpeed * dt;
          fingers.forEach(
            (f) =>
              (f.mesh.rotation.x = THREE.MathUtils.lerp(
                f.mesh.rotation.x,
                -2.0,
                0.15
              ))
          );

          const descentLimit = minimumClawCenterY(state.claw.x, state.claw.z);
          if (state.claw.y <= descentLimit) {
            state.claw.y = descentLimit;
            stopClawEffects();
            state.mode = "GRABBING";
            let best = null,
              minD = CFG.grabRadius;
            const tipY = state.claw.y - 4.0;

            prizes.forEach((p) => {
              const dx = p.mesh.position.x - state.claw.x;
              const dy = p.mesh.position.y - tipY;
              const dz = p.mesh.position.z - state.claw.z;
              const d = Math.sqrt(dx * dx + dy * dy + dz * dz);
              if (d < minD) {
                minD = d;
                best = p;
              }
            });
            setTimeout(() => {
              if (best && Math.random() < CFG.gripStrength) {
                state.grabbed = best;
                clawGroup.getWorldPosition(_clawWorldPos);
                state.grabOffset.copy(best.mesh.position).sub(_clawWorldPos);
                best.body.type = CANNON.Body.KINEMATIC;
                best.body.collisionFilterMask = 0;
                best.body.velocity.set(0, 0, 0);
                best.body.angularVelocity.set(0, 0, 0);
              }
              state.mode = "ASCENDING";
              playClawEffect(clawAscendingSound);
            }, 500);
          }
        } else if (state.mode === "GRABBING") {
          // FIX: Consistent hold angle (0.1) for both phases
          const targetAngle = state.grabbed ? 0.1 : 0.5;
          fingers.forEach(
            (f) =>
              (f.mesh.rotation.x = THREE.MathUtils.lerp(
                f.mesh.rotation.x,
                targetAngle,
                0.08
              ))
          );
        } else if (state.mode === "ASCENDING") {
          state.claw.y += CFG.liftSpeed * dt;
          // FIX: SLOW LERP (0.05) for smooth hold
          const targetAngle = state.grabbed ? 0.1 : 0.5;
          fingers.forEach(
            (f) =>
              (f.mesh.rotation.x = THREE.MathUtils.lerp(
                f.mesh.rotation.x,
                targetAngle,
                0.05
              ))
          );

          if (state.grabbed) {
            const idealOffset = new THREE.Vector3(0, -3.8, 0);
            state.grabOffset.lerp(idealOffset, 0.03);
            clawGroup.getWorldPosition(_clawWorldPos);
            clawGroup.getWorldQuaternion(_clawWorldQuat);
            const pos = new THREE.Vector3()
              .copy(state.grabOffset)
              .applyQuaternion(_clawWorldQuat)
              .add(_clawWorldPos);
            state.grabbed.body.position.copy(pos);
            state.grabbed.body.velocity.set(0, 0, 0);
            state.grabbed.body.angularVelocity.set(0, 0, 0);
            state.grabbed.body.quaternion.copy(_clawWorldQuat);
          }
          if (state.claw.y >= 22) {
            stopClawEffects();
            state.mode = "RETURNING";
          }
        } else if (state.mode === "RETURNING") {
          const targetAngle = state.grabbed ? 0.1 : 0.5;
          fingers.forEach(
            (f) =>
              (f.mesh.rotation.x = THREE.MathUtils.lerp(
                f.mesh.rotation.x,
                targetAngle,
                0.05
              ))
          );

          const tx = -10,
            tz = 10;
          const dx = tx - state.claw.x,
            dz = tz - state.claw.z;
          const d = Math.sqrt(dx * dx + dz * dz);
          const spd = CFG.clawSpeed * dt;

          if (d < 0.5) {
            state.mode = "DROPPING";
            if (state.grabbed) {
              state.grabbed.body.type = CANNON.Body.DYNAMIC;
              state.grabbed.body.collisionFilterMask =
                G_DEFAULT | G_PRIZE | G_CLAW;
              state.grabbed.body.velocity.set(0, -5, 0);
              state.grabbed.body.angularVelocity.set(0, 0, 0);
              state.grabbed.body.wakeUp();

              state.grabbed.body.collisionFilterMask = G_DEFAULT | G_PRIZE;
              const g = state.grabbed;
              setTimeout(() => {
                if (g && g.body)
                  g.body.collisionFilterMask = G_DEFAULT | G_PRIZE | G_CLAW;
              }, 1000);
              state.grabbed = null;
            }
            setTimeout(() => {
              state.mode = "IDLE";
              state.timerActive = false;
              state.timerValue = TIMER_DURATION;
              state.creditCharged = false;
              // Mantém o ID até a próxima rodada. O prêmio ainda pode estar
              // caindo até a área de coleta depois que a garra retorna.
            }, 1000);
          } else {
            state.claw.x += (dx / d) * spd;
            state.claw.z += (dz / d) * spd;
            if (state.grabbed) {
              clawGroup.getWorldPosition(_clawWorldPos);
              clawGroup.getWorldQuaternion(_clawWorldQuat);
              const pos = new THREE.Vector3()
                .copy(state.grabOffset)
                .applyQuaternion(_clawWorldQuat)
                .add(_clawWorldPos);
              state.grabbed.body.position.copy(pos);
              state.grabbed.body.velocity.set(0, 0, 0);
              state.grabbed.body.angularVelocity.set(0, 0, 0);
              state.grabbed.body.quaternion.copy(_clawWorldQuat);
            }
          }
        } else if (state.mode === "DROPPING") {
          fingers.forEach(
            (f) =>
              (f.mesh.rotation.x = THREE.MathUtils.lerp(
                f.mesh.rotation.x,
                -1.0,
                0.2
              ))
          );
        }

        const railY = 41;
        const L = Math.max(0.1, railY - state.claw.y);
        clawCab.scale.y = L / 40;
        clawCab.position.y = 0;

        if (railPivot) {
          railPivot.position.x = state.claw.x;
          railPivot.position.z = state.claw.z;
          clawGroup.position.set(0, -L, 0);

          const velX = (state.claw.x - prevClawX) / Math.max(dt, 0.001);
          const velZ = (state.claw.z - prevClawZ) / Math.max(dt, 0.001);
          const pivotAccX = (velX - prevVelX) / Math.max(dt, 0.001);
          const pivotAccZ = (velZ - prevVelZ) / Math.max(dt, 0.001);
          prevClawX = state.claw.x;
          prevClawZ = state.claw.z;
          prevVelX = velX;
          prevVelZ = velZ;

          const ropeLen = Math.max(2.5, L);

          const alphaZ =
            -(PENDULUM_G / ropeLen) * Math.sin(swingZ) -
            (pivotAccX / ropeLen) * Math.cos(swingZ) -
            PENDULUM_DAMPING * swingVelZ;
          const alphaX =
            -(PENDULUM_G / ropeLen) * Math.sin(swingX) +
            (pivotAccZ / ropeLen) * Math.cos(swingX) -
            PENDULUM_DAMPING * swingVelX;

          swingVelZ = THREE.MathUtils.clamp(swingVelZ + alphaZ * dt, -9, 9);
          swingVelX = THREE.MathUtils.clamp(swingVelX + alphaX * dt, -9, 9);
          swingZ = THREE.MathUtils.clamp(
            swingZ + swingVelZ * dt,
            -MAX_SWING,
            MAX_SWING
          );
          swingX = THREE.MathUtils.clamp(
            swingX + swingVelX * dt,
            -MAX_SWING,
            MAX_SWING
          );

          const GLASS_MARGIN = 14;
          const maxSwingZ = Math.asin(
            Math.min(
              1,
              Math.max(0, GLASS_MARGIN - Math.abs(state.claw.x)) / ropeLen
            )
          );
          const maxSwingX = Math.asin(
            Math.min(
              1,
              Math.max(0, GLASS_MARGIN - Math.abs(state.claw.z)) / ropeLen
            )
          );

          if (swingZ > maxSwingZ) {
            swingZ = maxSwingZ;
            swingVelZ = Math.min(swingVelZ, 0);
          }
          if (swingZ < -maxSwingZ) {
            swingZ = -maxSwingZ;
            swingVelZ = Math.max(swingVelZ, 0);
          }
          if (swingX > maxSwingX) {
            swingX = maxSwingX;
            swingVelX = Math.min(swingVelX, 0);
          }
          if (swingX < -maxSwingX) {
            swingX = -maxSwingX;
            swingVelX = Math.max(swingVelX, 0);
          }

          railPivot.rotation.x = swingX;
          railPivot.rotation.z = swingZ;
        }

        // Atualiza os proxies cinemáticos antes do passo da física e informa
        // suas velocidades ao Cannon. Isso reduz o tunneling em movimentos
        // rápidos e faz as hastes empurrarem os prêmios de forma natural.
        for (let i = 0; i < 3; i++) {
          const proxy = state.fingerBodies[i];
          if (!proxy) continue;
          const angle = fingers[i].angleOffset;
          const rX = fingers[i].mesh.rotation.x;
          const pivotOffset = { x: 0, y: -0.5, z: 1.2 };
          const boxDist = 2.55;
          const localY = -boxDist * Math.cos(rX) - 0.35 * Math.sin(rX);
          const localZ = -boxDist * Math.sin(rX) + 0.35 * Math.cos(rX);
          const fy = pivotOffset.y + localY;
          const fz = pivotOffset.z + localZ;
          const lx = fz * Math.sin(angle);
          const lz = fz * Math.cos(angle);
          const nx = state.claw.x + lx;
          const ny = state.claw.y + fy;
          const nz = state.claw.z + lz;
          const last = proxy._lastPosition || proxy.position;
          proxy.velocity.set(
            (nx - last.x) / Math.max(dt, 0.001),
            (ny - last.y) / Math.max(dt, 0.001),
            (nz - last.z) / Math.max(dt, 0.001)
          );
          // Corpos cinemáticos podem gerar impulsos enormes ao mudar de posição.
          // Limitar sua velocidade mantém o contato firme sem lançar os prêmios.
          const maxFingerVelocity = 7.0;
          proxy.velocity.x = THREE.MathUtils.clamp(proxy.velocity.x, -maxFingerVelocity, maxFingerVelocity);
          proxy.velocity.y = THREE.MathUtils.clamp(proxy.velocity.y, -maxFingerVelocity, maxFingerVelocity);
          proxy.velocity.z = THREE.MathUtils.clamp(proxy.velocity.z, -maxFingerVelocity, maxFingerVelocity);
          proxy.position.set(nx, ny, nz);
          const q = new CANNON.Quaternion();
          q.setFromEuler(-rX, angle, 0, "XYZ");
          proxy.quaternion.copy(q);
          if (!proxy._lastPosition) proxy._lastPosition = new CANNON.Vec3();
          proxy._lastPosition.copy(proxy.position);
          proxy.aabbNeedsUpdate = true;
          proxy.wakeUp();
        }

        if (state.clawCoreBody) {
          const core = state.clawCoreBody;
          const nx = state.claw.x;
          const ny = state.claw.y;
          const nz = state.claw.z;
          const last = core._lastPosition || core.position;
          core.velocity.set(
            (nx - last.x) / Math.max(dt, 0.001),
            (ny - last.y) / Math.max(dt, 0.001),
            (nz - last.z) / Math.max(dt, 0.001)
          );
          core.position.set(nx, ny, nz);
          if (!core._lastPosition) core._lastPosition = new CANNON.Vec3();
          core._lastPosition.copy(core.position);
          core.aabbNeedsUpdate = true;
          core.wakeUp();
        }
      }



      function ensureWinOverlay() {
        let overlay = document.getElementById("win-overlay");
        if (overlay) return overlay;
        overlay = document.createElement("div");
        overlay.id = "win-overlay";
        overlay.innerHTML = `
          <div id="win-card">
            <div class="win-small">ATOS TELECOM</div>
            <h2>PARABÉNS!</h2>
            <p id="win-prize-text">VOCÊ GANHOU UM PRÊMIO!</p>
            <p id="win-instruction">TIRE UM PRINT OU FOTO DESTA TELA PARA REIVINDICAR SEU PRÊMIO.</p>
            <div id="win-token-label">TOKEN DO PRÊMIO</div>
            <div id="win-token">AGUARDE...</div>
            <button id="win-close" type="button">FECHAR</button>
          </div>`;
        overlay.querySelector("#win-close")?.addEventListener("click", () => overlay.classList.remove("show"));
        document.body.appendChild(overlay);
        return overlay;
      }

      function launchConfetti() {
        const colors = ["#ffd700", "#ffffff", "#19d36b", "#ff4fd8", "#00d9ff"];
        for (let i = 0; i < 130; i++) {
          const piece = document.createElement("span");
          piece.className = "confetti-piece";
          piece.style.left = `${Math.random() * 100}vw`;
          piece.style.background = colors[Math.floor(Math.random() * colors.length)];
          piece.style.setProperty("--duration", `${2.4 + Math.random() * 2.4}s`);
          piece.style.setProperty("--drift", `${-180 + Math.random() * 360}px`);
          piece.style.setProperty("--rotation", `${Math.random() * 360}deg`);
          piece.style.borderRadius = Math.random() > 0.55 ? "50%" : "2px";
          document.body.appendChild(piece);
          setTimeout(() => piece.remove(), 5200);
        }
      }

      function showPrizeWin(prizeName, token) {
        const overlay = ensureWinOverlay();
        const prizeText = overlay.querySelector("#win-prize-text");
        if (prizeText) prizeText.textContent = `VOCÊ GANHOU ${prizeName || "UM PRÊMIO"}`;
        const tokenText = overlay.querySelector("#win-token");
        if (tokenText) tokenText.textContent = token || "CONFIRME NA ATOS TELECOM";
        launchConfetti();
        overlay.classList.add("show");
        clearTimeout(showPrizeWin._timer);
        showPrizeWin._timer = setTimeout(() => overlay.classList.remove("show"), 30000);
      }

      let lastFrameTime = performance.now();
      function animate(now = performance.now()) {
        requestAnimationFrame(animate);
        const dt = Math.min((now - lastFrameTime) / 1000, 1 / 30);
        lastFrameTime = now;
        updateGame(dt);
        updateCameraOrbit();
        // 60 Hz com até 3 subpassos mantém estabilidade e reduz bastante o custo
        // comparado ao passo fixo de 120 Hz usado anteriormente.
        world.step(1 / 60, dt, 3);
        prizes.forEach((p) => {
          p.mesh.position.copy(p.body.position);
          p.mesh.quaternion.copy(p.body.quaternion);
          if (
            p.mesh.position.y < -30 &&
            p.mesh.position.x < -5 &&
            p.mesh.position.z > 5 &&
            !p.scored
          ) {
            p.scored = true;
            const prizeType = p.mesh.userData.prizeType;
            const isWinningPrize = prizeType === "gift" || prizeType === "logo";
            if (isWinningPrize) {
              state.score++;
              const scoreEl = document.getElementById("score");
              if (scoreEl) scoreEl.innerText = state.score;
              const partidaId = state.currentPartidaId;
              if (partidaId) {
                fetch('/api/game?acao=resgatar-premio', {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({ token: atosGameToken, partidaId })
                }).then(async (resp) => {
                  const dados = await resp.json().catch(() => ({}));
                  if (resp.ok && dados.ok && dados.premio && dados.token) {
                    showPrizeWin(dados.premio, dados.token);
                    state.currentPartidaId = null;
                  } else {
                    console.error('Falha ao resgatar prêmio:', dados);
                    showPrizeWin('NÃO FOI POSSÍVEL CONFIRMAR O PRÊMIO', 'PROCURE A ATOS TELECOM');
                  }
                }).catch((erro) => {
                  console.error('Falha de rede ao resgatar prêmio:', erro);
                  showPrizeWin('UM PRÊMIO — PROCURE A ATOS TELECOM');
                });
              } else {
                showPrizeWin('UM PRÊMIO — PROCURE A ATOS TELECOM');
              }
            }
            scene.remove(p.mesh);
            world.removeBody(p.body);
          }
          if (p.mesh.position.y < -50) {
            p.body.position.set(0, 20, 0);
            p.body.velocity.set(0, 0, 0);
          }
        });
        renderer.render(scene, camera);
      }

      window.onresize = () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
      };

      init();
